import { chromium } from 'playwright-core';
import assert from 'node:assert/strict';
import { mkdir } from 'node:fs/promises';
const browser = await chromium.launch({ executablePath: process.env.CHROME_PATH ?? '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: true });
try {
 await mkdir('/tmp/malink-settings-qa', { recursive: true });
 for (const width of [390, 1280]) {
  const page = await browser.newPage({ viewport: { width, height: 844 } });
  await page.emulateMedia({ reducedMotion: 'reduce' });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto(process.env.SETTINGS_FIXTURE_URL ?? 'http://127.0.0.1:4179/malink/tests/fixtures/computer-settings/');
  await page.getByRole('button', { name: 'Manage Tokyo server · Tokyo', exact: true }).waitFor();
  await page.screenshot({ path: `/tmp/malink-settings-qa/list-${width}.png` });
  await page.getByRole('button', { name: 'Manage Tokyo server · Tokyo', exact: true }).click();
  await page.getByRole('button', { name: 'Update', exact: true }).waitFor();
  assert.equal(await page.getByRole('heading', { name: 'Execution tracks' }).isVisible(), false);
  assert.equal(await page.evaluate(() => window.checks), 1);
  assert.equal(await page.getByRole('dialog').count(), 1);
  assert.equal(await page.getByRole('button', { name: 'Check available versions' }).count(), 0);
  await page.getByRole('button', { name: 'Update', exact: true }).click();
  assert.equal(await page.evaluate(() => window.updatedNode), 'tokyo');
  await page.getByRole('button', { name: 'All computers' }).click();
  await page.getByRole('button', { name: 'Manage Mac mini · Office', exact: true }).click();
  assert.equal(await page.getByRole('button', { name: 'Manage Tokyo server · Tokyo' }).count(), 0);
  await page.getByRole('button', { name: 'Update', exact: true }).click();
  assert.equal(await page.evaluate(() => window.updatedNode), 'mac');
  await page.getByRole('button', { name: 'All computers' }).click();
  await page.getByRole('button', { name: 'Manage Tokyo server · Tokyo', exact: true }).click();
  await page.screenshot({ path: `/tmp/malink-settings-qa/detail-${width}.png` });
  const panel = () => page.locator('.computer-action-dialog').last();
  const screenshot = async name => {
    await page.screenshot({ path: `/tmp/malink-settings-qa/${name}-${width}.png` });
    const overflow = await page.evaluate(() => [...document.querySelectorAll('.computer-action-dialog, .computer-action-body')].filter(el => el.scrollWidth > el.clientWidth + 2).map(el => el.className));
    assert.deepEqual(overflow, []);
  };
  await page.getByRole('button', { name: /^Update activity/ }).click();
  await screenshot('activity');
  await panel().getByRole('button', { name: 'View update session', exact: true }).click();
  await page.getByRole('heading', { name: 'Update session' }).waitFor();
  await page.getByRole('button', { name: 'Back to computer settings' }).click();
  assert.equal(await page.evaluate(() => window.checks), 1);
  await page.evaluate(() => window.setFixturePhase('staged'));
  await page.getByRole('button', { name: 'Install when idle', exact: true }).scrollIntoViewIfNeeded();
  await screenshot('ready');
  await page.getByRole('button', { name: /^Update activity/ }).click();
  await panel().getByRole('button', { name: 'Install and restart now…', exact: true }).click();
  await screenshot('force-confirm');
  await panel().getByRole('button', { name: 'Keep working', exact: true }).click();
  await page.keyboard.press('Escape');
  assert.equal(await page.locator('.computer-action-dialog').count(), 0);
  await page.evaluate(() => window.setFixturePhase('committed'));
  await page.getByRole('button', { name: /^Versions Installed/ }).click();
  await screenshot('versions');
  await panel().getByRole('button', { name: /Use this version v1/ }).click();
  assert.equal(await page.evaluate(() => window.selectedVersion), undefined);
  await screenshot('switch-confirm');
  await panel().getByRole('button', { name: 'Confirm switch', exact: true }).click();
  assert.equal(await page.evaluate(() => window.selectedVersion), 'v1');
  assert.equal(await panel().getByRole('button', { name: /Use this version v2/ }).count(), 1);
  await page.keyboard.press('Escape');
  assert.equal(await page.locator('.computer-action-dialog').count(), 0);
  await page.getByRole('button', { name: /^Rename Tokyo/ }).click();
  await panel().getByRole('textbox', { name: 'Computer name' }).fill('Home computer');
  await screenshot('rename');
  await panel().getByRole('button', { name: 'Save', exact: true }).click();
  await page.getByText('Home computer · Tokyo', { exact: true }).waitFor();
  await page.getByRole('button', { name: /^Restart Gateway Apply/ }).click();
  assert.equal(await page.evaluate(() => window.restart), undefined);
  await screenshot('restart');
  await panel().getByRole('button', { name: /^Restart immediately/ }).click();
  await screenshot('restart-confirm');
  await page.keyboard.press('Escape');
  assert.equal(await page.locator('.computer-action-dialog').count(), 1);
  await panel().getByRole('button', { name: 'Restart when idle', exact: true }).click();
  assert.deepEqual(await page.evaluate(() => window.restart), {id:'tokyo', project:'project', mode:'when_idle'});
  await screenshot('restart-waiting');
  await page.keyboard.press('Escape');
  await page.evaluate(() => window.setFixtureOffline(true));
  await page.getByRole('button', { name: 'Connection help', exact: true }).click();
  await screenshot('connection');
  await panel().getByRole('button', { name: /^Technical record/ }).click();
  await screenshot('technical');
  await page.keyboard.press('Escape');
  await panel().getByRole('button', { name: /^Send diagnostics/ }).click();
  await screenshot('diagnostics');
  await panel().getByRole('button', { name: 'Export diagnostics', exact: true }).click();
  assert.equal(await page.evaluate(() => window.exported), true);
  await page.keyboard.press('Escape');
  await page.keyboard.press('Escape');
  await page.getByRole('button', { name: /^Remove or reconnect/ }).click();
  await screenshot('remove');
  assert.equal(await panel().getByRole('button', { name: 'Continue without this computer…', exact: true }).isDisabled(), true);
  await page.evaluate(() => window.setFixtureCanRemove(true));
  await panel().getByRole('button', { name: 'Continue without this computer…', exact: true }).click();
  await screenshot('remove-confirm');
  assert.equal(await page.evaluate(() => window.retirement), undefined);
  await panel().getByRole('button', { name: 'Remove computer and continue', exact: true }).click();
  assert.deepEqual(await page.evaluate(() => window.retirement), {id:'tokyo', authority:'mac-project'});
  await screenshot('removing');
  await page.evaluate(() => window.finishRetirement());
  await page.waitForFunction(() => document.querySelectorAll('.computer-action-dialog').length === 1);
  await page.keyboard.press('Escape');
  await page.evaluate(() => { window.setFixtureOffline(false); window.setFixturePhase('failed'); });
  await page.getByRole('button', { name: /^Connection & recovery/ }).click();
  await screenshot('failure');
  await page.keyboard.press('Escape');
  const overflow = await page.evaluate(() => [...document.querySelectorAll('.matrix-settings, .matrix-settings-body, .computer-details')].filter(el => el.scrollWidth > el.clientWidth + 2).map(el => el.className));
  await page.evaluate(() => window.setFixturePhase('committed'));
  await page.getByRole('button', { name: /^Versions Installed/ }).click();
  await panel().getByRole('button', { name: /Use this version v1/ }).click();
  assert.equal(await page.evaluate(() => document.getElementById('root').inert), true);
  await page.evaluate(() => window.setFixtureSessionOpen(true));
  await page.getByRole('heading', { name: 'Update session' }).waitFor();
  assert.equal(await page.evaluate(() => document.getElementById('root').inert), false);
  assert.notEqual(await page.evaluate(() => document.body.style.overflow), 'hidden');
  assert.deepEqual(overflow, []);
  assert.deepEqual(errors, []);
  console.log(JSON.stringify({ width, checks: 1, versionSelected: 'v1', overflow, errors }));
  await page.close();
 }
} finally { await browser.close(); }
